from typing import Dict, Any, Tuple
class MovementComponent:
    def __init__(self, config: Dict[str, Any]):
        self.movement_type: str = config.get('type', 'generic')
        self.move_speed: float = float(config.get('move_speed', 0))
        self.jump_height: float = float(config.get('jump_height', 0))
        self._special_abilities: Dict[str, Any] = config.get('special_abilities', {})
        # Teleport specific attributes
        teleport_config = self._special_abilities.get('teleport', {})
        self.teleport_range: float = float(teleport_config.get('range', 0))
        self.teleport_cooldown: float = float(teleport_config.get('cooldown', 0))
        self._teleport_current_cooldown: float = 0.0
    def update(self, delta_time: float):
        if self._teleport_current_cooldown > 0:
            self._teleport_current_cooldown -= delta_time
            if self._teleport_current_cooldown < 0:
                self._teleport_current_cooldown = 0.0
    def move(self, delta_time: float, direction_x: float) -> float:
        return direction_x  self.move_speed  delta_time
    def jump(self) -> float:
        return self.jump_height
    def can_teleport(self) -> bool:
        return self._teleport_current_cooldown <= 0 and self.teleport_range > 0
    def teleport(self, current_position: Tuple[float, float], target_position: Tuple[float, float]) -> Tuple[float, float]:
        if not self.can_teleport():
            return current_position
